Sure, here's an example C++ program that reads a text file line by line and counts the number of occurrences of a specific word:

```c++
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

int main() {
    std::string filename, search_word;
    std::unordered_map<std::string, int> word_count;

    // Get input from user
    std::cout << "Enter file name: ";
    std::getline(std::cin, filename);

    std::cout << "Enter word to search: ";
    std::getline(std::cin, search_word);

    // Open file for reading
    std::ifstream file(filename);

    if (!file.is_open()) {
