        return 1;
    }

    // Read file line by line and count occurrences of search word
    std::string line;
    while (std::getline(file, line)) {
        std::size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != std::string::npos) {
            word_count[search_word]++;
            pos += search_word.length();
        }
    }

    // Close file
    file.close();

    // Print results
    std::cout << "Search word: " << search_word << std::endl;
    std::cout << "Occurrence count: " << word_count[search_word] << std::endl;

    return 0;
}
```

